def load_jin10_news():
    """加载金十数据"""
    if JIN10_DATA_FILE.exists():
        try:
            with open(JIN10_DATA_FILE, 'r', encoding='utf-8') as f:
                data = json.load(f)
                return data.get('news', [])
        except:
            return []
    return []

def jin10_to_rss(news_list):
    """将金十新闻转换为RSS XML"""
    root = ET.Element('rss', version='2.0')
    channel = ET.SubElement(root, 'channel')
    ET.SubElement(channel, 'title').text = '金十数据 - 实时财经日历'
    ET.SubElement(channel, 'link').text = 'https://www.gold.cn'
    ET.SubElement(channel, 'description').text = f'金十数据 {len(news_list)} 条新闻'
    ET.SubElement(channel, 'language').text = 'zh-cn'
    ET.SubElement(channel, 'lastBuildDate').text = datetime.now().strftime('%a, %d %b %Y %H:%M:%S GMT')

    for n in news_list[:50]:
        item = ET.SubElement(channel, 'item')
        ET.SubElement(item, 'title').text = n.get('title', '') or n.get('data', {}).get('title', '')
        ET.SubElement(item, 'link').text = 'https://www.gold.cn'
        ET.SubElement(item, 'description').text = n.get('data', {}).get('event', '')
        ET.SubElement(item, 'pubDate').text = datetime.now().strftime('%a, %d %b %Y %H:%M:%S GMT')

    return '<?xml version="1.0" encoding="UTF-8"?>\n' + ET.tostring(root, encoding='unicode')

